40\\u0448\\u0430\\u043D\\u0441\\u043A\",\"\\u041C\\u043E\\u0441\\u043A\\u0432\\u0430\",\"\\u041C\\u043E\\u0441\\u043A\\u0432\\u0430, \\u041C\\u0413\\u0423\",\"\\u041C\\u043E\\u0441\\u0442\\u043E\\u0432\\u0441\\u043A\\u043E\\u0439\",\"\\u041C\\u0443\\u0440\\u0430\\u0432\\u043B\\u0435\\u043D\\u043A\\u043E\",\"\\u041C\\u0443\\u0440\\u0430\\u0448\\u0438\",\"\\u041C\\u0443\\u0440\\u043C\\u0430\\u043D\\u0441\\u043A\",\"\\u041C\\u0443\\u0440\\u043E\\u043C\",\"\\u041C\\u0446\\u0435\\u043D\\u0441\\u043A\",\"\\u041C\\u044B\\u0441 \\u0428\\u043C\\u0438\\u0434\\u0442\\u0430\",\"\\u041C\\u044B\\u0442\\u0438\\u0449\\u0438\",\"\\u041D\\u0430\\u0431\\u0435\\u0440\\u0435\\u0436\\u043D\\u044B\\u0435 \\u0427\\u0435\\u043B\\u043D\\u044B\",\"\\u041D\\u0430\\u0434\\u044B\\u043C\",\"\\u041D\\u0430\\u0437\\u0440\\u0430\\u043D\\u044C\",\"\\u041D\\u0430\\u043B\\u044C\\u0447\\u0438\\u043A\",\"\\u041D\\u0430\\u0440\\u043E-\\u0424\\u043E\\u043C\\u0438\\u043D\\u0441\\u043A\",\"\\u041D\\u0430\\u0440\\u0442\\u043A\\u0430\\u043B\\u0430\",\"\\u041D\\u0430\\u0440\\u044B\\u043C\",\"\\u041D\\u0430\\u0440\\u044C\\u044F\\u043D-\\u041C\\u0430\\u0440\",\"\\u041D\\u0430\\u0445\\u043E\\u0434\\u043A\\u0430\",\"\\u041D\\u0435\\u0432\\u0435\\u043B\\u044C\\u0441\\u043A\",\"\\u041D\\u0435\\u0432\\u0438\\u043D\\u043D\\u043E\\u043C\\u044B\\u0441\\u0441\\u043A\",\"\\u041D\\u0435\\u0432\\u044C\\u044F\\u043D\\u0441\\u043A\",\"\\u041D\\u0435\\u043F\\u043B\\u044E\\u0435\\u0432\\u043A\\u0430\",\"\\u041D\\u0435\\u0440\\u0447\\u0438\\u043D\\u0441\\u043A\",\"\\u041D\\u0435\\u0444\\u0435\\u0434\\u043E\\u0432\\u0430\",\"\\u041D\\u0435\\u0444\\u0442\\u0435\\u0433\\u043E\\u0440\\u0441\\u043A (\\u0421\\u0430\\u043C\\u0430\\u0440.)\",\"\\u041D\\u0435\\u0444\\u0442\\u0435\\u043A\\u0430\\u043C\\u0441\\u043A\",\"\\u041D\\u0435\\u0444\\u0442\\u0435\\u044E\\u0433\\u0430\\u043D\\u0441\\u043A\",\"\\u041D\\u0438\\u0436\\u043D\\u0435\\u0432\\u0430\\u0440\\u0442\\u043E\\u0432\\u0441\\u043A\",\"\\u041D\\u0438\\u0436\\u043D\\u0435\\u043A\\u0